+function optionDependencyTerm(usage: Usage): Extract<UsageTerm, { type: "option" }> | undefined {
+  for (const term of usage) {
+    if (term.type === "option") return term;
+    if (term.type === "optional" || term.type === "multiple") {
+      const nested = optionDependencyTerm(term.terms);
+      if (nested) return nested;
+    }
