+  return undefined;
+}
+
+function dependencyValue(state: unknown): unknown {
+  if (Array.isArray(state)) return dependencyValue(state[0]);
+  if (isDependencySourceState(state)) return dependencyValue(state.result);
+  if (
+    state != null && typeof state === "object" &&
+    "success" in state && (state as { success?: unknown }).success === true &&
+    "value" in state
+  ) return (state as { value: unknown }).value;
+  return state;
+}
+
+function dependencySatisfied(
+  condition: OptionDependencyCondition,
+  states: Record<string | symbol, unknown>,
+  fields: ReadonlyMap<string, string | symbol>,
+): boolean {
+  if (typeof condition === "string") {
+    const field = fields.get(condition);
+    return field == null ? false : Boolean(dependencyValue(states[field]));
+  }
+  if ("option" in condition) {
+    const field = fields.get(condition.option);
+    if (field == null) return false;
+    const actual = dependencyValue(states[field]);
+    return "value" in condition ? actual === condition.value : Boolean(actual);
+  }
+  const allOf = condition.allOf;
+  const anyOf = condition.anyOf;
+  return (allOf == null || allOf.every((item) => dependencySatisfied(item, states, fields))) &&
+    (anyOf == null || anyOf.some((item) => dependencySatisfied(item, states, fields)));
+}
+
+function dependencyConfiguration(
+  usage: Usage,
+): OptionDependencyOptions | undefined {
